-- Materi contoh: HTML Level 1, step 1-3 (step 4-5 = mini game dan kuis, tahap 8-9). Aman dijalankan ulang.
UPDATE lessons SET content='<h3>Apa itu HTML?</h3><p><b>HTML</b> (HyperText Markup Language) adalah bahasa untuk menyusun <b>struktur</b> halaman web: judul, paragraf, gambar, tautan, dan lainnya.</p><p>HTML ditulis dengan <b>tag</b>. Tag biasanya berpasangan: tag pembuka dan tag penutup.</p><pre class="code-ex"><span>&lt;p&gt;Halo, dunia!&lt;/p&gt;</span></pre><ul><li><code>&lt;p&gt;</code> adalah tag pembuka</li><li><code>Halo, dunia!</code> adalah isi</li><li><code>&lt;/p&gt;</code> adalah tag penutup</li></ul><p>Gabungan tag pembuka, isi, dan tag penutup disebut <b>element</b>.</p>' WHERE step_no=1 AND level_id=(SELECT l.id FROM levels l JOIN modules m ON m.id=l.module_id WHERE m.slug='html' AND l.level_no=1);
UPDATE lessons SET content='<p>Setiap halaman HTML punya kerangka yang sama. Klik penjelasan di kanan untuk menyorot barisnya.</p><div class="row g-3"><div class="col-md-7"><pre class="code-ex"><span data-i="1">&lt;!DOCTYPE html&gt;</span><span data-i="2">&lt;html lang="id"&gt;</span><span data-i="3">&lt;head&gt;&lt;title&gt;Halamanku&lt;/title&gt;&lt;/head&gt;</span><span data-i="4">&lt;body&gt;</span><span data-i="5">  &lt;h1&gt;Judul&lt;/h1&gt;&lt;p&gt;Paragraf&lt;/p&gt;</span><span data-i="4">&lt;/body&gt;&lt;/html&gt;</span></pre></div><div class="col-md-5"><ol class="ex-list"><li data-i="1">Memberi tahu browser bahwa ini dokumen HTML5.</li><li data-i="2">Element akar yang membungkus seluruh halaman. <code>lang="id"</code> menandakan bahasa Indonesia.</li><li data-i="3">Informasi halaman. <code>title</code> tampil di tab browser.</li><li data-i="4">Seluruh isi yang tampil di layar berada di dalam <code>body</code>.</li><li data-i="5"><code>h1</code> adalah heading utama, <code>p</code> adalah paragraf.</li></ol></div></div>' WHERE step_no=2 AND level_id=(SELECT l.id FROM levels l JOIN modules m ON m.id=l.module_id WHERE m.slug='html' AND l.level_no=1);
UPDATE lessons SET content='<p>Tulis satu heading <code>&lt;h1&gt;</code> berisi judul dan satu paragraf <code>&lt;p&gt;</code> berisi perkenalan singkat di dalam <code>body</code>. Klik <b>Run Code</b> untuk melihat hasilnya, lalu <b>Complete Step</b> untuk diperiksa.</p>',starter_code='<!DOCTYPE html>
<html>
<body>
  <!-- Tulis h1 dan p di bawah ini -->

</body>
</html>',check_rules='[{"re": "<h1[^>]*>\\\\s*\\\\S.*?</h1>", "msg": "Belum ada heading. Tulis <h1>Judulmu</h1> dan pastikan ada isi serta tag penutup </h1>."}, {"re": "<p[^>]*>\\\\s*\\\\S.*?</p>", "msg": "Belum ada paragraf. Tulis <p>Perkenalanmu</p> dan pastikan tag penutup </p> ada."}]' WHERE step_no=3 AND level_id=(SELECT l.id FROM levels l JOIN modules m ON m.id=l.module_id WHERE m.slug='html' AND l.level_no=1);
